      <div class="mp-filter-row"><nav class="mp-tabs" aria-label="Artifact type"><button class="active" data-kind=""><?= htmlspecialchars($t['all'], ENT_QUOTES, 'UTF-8') ?></button><button data-kind="node"><?= htmlspecialchars($t['node'], ENT_QUOTES, 'UTF-8') ?></button><button data-kind="flowmap"><?= htmlspecialchars($t['flowmap'], ENT_QUOTES, 'UTF-8') ?></button><button data-kind="workspace"><?= htmlspecialchars($t['workspace'], ENT_QUOTES, 'UTF-8') ?></button></nav><label class="mp-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.3"></circle><path d="m16 16 4.2 4.2"></path></svg><input id="mp-query" type="search" placeholder="<?= htmlspecialchars($t['search'], ENT_QUOTES, 'UTF-8') ?>" autocomplete="off"></label></div>
      <div class="mp-meta"><strong id="mp-count">—</strong><span id="mp-page"></span></div><div id="mp-results" class="mp-grid"><div class="mp-state"><strong><?= htmlspecialchars($t['loading'], ENT_QUOTES, 'UTF-8') ?></strong></div></div><div class="mp-page"><button id="mp-prev" disabled><?= htmlspecialchars($t['prev'], ENT_QUOTES, 'UTF-8') ?></button><span id="mp-page-controls"></span><button id="mp-next" disabled><?= htmlspecialchars($t['next'], ENT_QUOTES, 'UTF-8') ?></button></div>
    </section>
  </main><footer class="mp-shell mp-foot">Trackers Lens · Public community catalog</footer>
  <script>
    (() => {
      const labels = <?= json_encode(['error' => $t['error'], 'empty' => $t['empty'], 'emptyText' => $t['emptyText'], 'free' => $t['free'], 'download' => $t['download'], 'license' => $t['license'], 'page' => $t['page']], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;
      const results = document.getElementById('mp-results'), query = document.getElementById('mp-query'), count = document.getElementById('mp-count'), pageLabel = document.getElementById('mp-page'), prev = document.getElementById('mp-prev'), next = document.getElementById('mp-next'), controls = document.getElementById('mp-page-controls');
      let kind = '', page = 1, timer = 0, request = 0;
      const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (ch) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
      const icon = (value) => ({node:'⬡',flowmap:'⌘',workspace:'▦'}[value] || '◇');
      async function load(nextPage = 1) {
        page = nextPage; const current = ++request;
        results.innerHTML = `<div class="mp-state"><strong>${esc(labels.loading || 'Loading…')}</strong></div>`;
        const params = new URLSearchParams({page:String(page)}); if(kind) params.set('kind',kind); if(query.value.trim()) params.set('query',query.value.trim());
        try {
          const response = await fetch(`/api/public/catalog?${params}`, {headers:{Accept:'application/json'}}); const data = await response.json(); if(!response.ok) throw new Error(data.message || labels.error); if(current !== request) return;
          count.textContent = `${data.total || 0} releases`; pageLabel.textContent = `${labels.page} ${data.page || page}`; controls.textContent = `${data.page || page}`; prev.disabled = (data.page || page) <= 1; next.disabled = !data.hasMore;
          if(!data.items?.length) { results.innerHTML = `<div class="mp-state"><strong>${esc(labels.empty)}</strong><span>${esc(labels.emptyText)}</span></div>`; return; }
          results.innerHTML = data.items.map(item => `<article class="mp-card"><div class="mp-cardtop"><span class="mp-icon" aria-hidden="true">${icon(item.kind)}</span><span class="mp-free">${esc(labels.free)}</span></div><span class="mp-kind">${esc(item.kind.toUpperCase())} · v${esc(item.version)}</span><h3>${esc(item.title)}</h3><p>${esc(item.description || '')}</p><div class="mp-cardfooter"><span>${esc(item.publisher || 'Trackers Lens creator')}</span><span>${esc(item.license || labels.license)}</span></div><a class="mp-dl" href="/app/marketplace?kind=${encodeURIComponent(item.kind)}&artifact=${encodeURIComponent(item.artifactId)}&version=${encodeURIComponent(item.version)}">${esc(labels.download)}</a></article>`).join('');
        } catch(error) { if(current !== request) return; count.textContent = ''; pageLabel.textContent = ''; prev.disabled = true; next.disabled = true; results.innerHTML = `<div class="mp-state"><strong>${esc(labels.error)}</strong><span>${esc(error.message)}</span></div>`; }
      }
      document.querySelectorAll('[data-kind]').forEach(button => button.addEventListener('click', () => { kind = button.dataset.kind; page = 1; document.querySelectorAll('[data-kind]').forEach(item => item.classList.toggle('active', item === button)); load(1); }));
      query.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(() => load(1), 250); }); prev.addEventListener('click', () => load(page - 1)); next.addEventListener('click', () => load(page + 1)); load(1);
    })();
  </script>
